def voyelles(phrase):
    total = 0
    for c in phrase.lower():
        if c in "aeiouy":
            total += 1
    return total

print(voyelles("Bonjour Hedi"))  # 5

def mention(note):
    if note >= 16:
        return "Très bien"
    elif note >= 14:
        return "Bien"
    elif note >= 12:
        return "Assez bien"
    elif note >= 10:
        return "Admis"
    else:
        return "Refusé"

print(mention(15.5))  # Bien

def bissextile(a):
    return (a % 4 == 0 and a % 100 != 0) or a % 400 == 0

print(bissextile(2028), bissextile(1900))  # True False

def moyenne(notes):
    return sum(notes) / len(notes)

print(moyenne([12, 15, 9, 18]))  # 13.5

def premier(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

print([k for k in range(2, 30) if premier(k)])

def fact(n):
    if n == 0:
        return 1
    return n * fact(n - 1)

print(fact(5))  # 120

def maximum(L):
    m = L[0]
    for x in L:
        if x > m:
            m = x
    return m

print(maximum([4, 9, 2, 7]))  # 9

def frequences(mot):
    d = {}
    for c in mot:
        d[c] = d.get(c, 0) + 1
    return d

print(frequences("banane"))  # {'b': 1, 'a': 2, 'n': 2, 'e': 1}

def f(x):
    return x ** 3 + x - 1

a, b = 0, 1
while b - a > 0.001:
    m = (a + b) / 2
    if f(a) * f(m) <= 0:
        b = m
    else:
        a = m
print(a, b)  # ≈ 0.6816 et 0.6826

def recherche(L, x):
    g, d = 0, len(L) - 1
    while g <= d:
        m = (g + d) // 2
        if L[m] == x:
            return True
        elif L[m] < x:
            g = m + 1
        else:
            d = m - 1
    return False

print(recherche([1, 3, 5, 8, 13], 8))  # True

def tri_selection(L):
    L = L.copy()
    for i in range(len(L)):
        j_min = i
        for j in range(i + 1, len(L)):
            if L[j] < L[j_min]:
                j_min = j
        L[i], L[j_min] = L[j_min], L[i]
    return L

print(tri_selection([5, 2, 9, 1]))  # [1, 2, 5, 9]

